  "hijos: {a} menores de 3 ({b} por entero) y {c} más ({d} por entero)": ["fills: {a} menors de 3 ({b} per enter) i {c} més ({d} per enter)", "children: {a} under 3 ({b} in full) and {c} more ({d} in full)"],
  "el {modelo}": ["el {modelo}", "Modelo {modelo}"],
  "Si domicilias el pago, hasta el {d}; {n}, hasta el {e}.": ["Si domicilies el pagament, fins al {d}; {n}, fins al {e}.", "If you pay by direct debit, by {d}; {n}, by {e}."],
  "Si domicilias el pago, hasta el {d}.": ["Si domicilies el pagament, fins al {d}.", "If you pay by direct debit, by {d}."],
