  // Modelos y plazos (lib/empresa.js modelosDe) y movimientos a Hacienda de Tesorería (lib/tesoreria.js)
  "IVA de la ventanilla única (ventas a particulares de la UE)": ["IVA de la finestreta única (vendes a particulars de la UE)", "One-stop shop VAT (sales to private customers in the EU)"],
  "IVA de compras a la UE o con inversión del sujeto pasivo (solo el trimestre en que las haya)": ["IVA de compres a la UE o amb inversió del subjecte passiu (només el trimestre en què n'hi hagi)", "VAT on EU purchases or under the reverse charge (only in quarters that have any)"],
  "Pago a cuenta del IRPF en módulos": ["Pagament a compte de l'IRPF en mòduls", "IRPF payment on account (módulos)"],
  "Resumen anual de esas retenciones": ["Resum anual d'aquestes retencions", "Annual summary of those withholdings"],
  "Retenciones del alquiler del local": ["Retencions del lloguer del local", "Premises rent withholdings"],
  "Retenciones de no residentes (alquiler, profesionales y otras rentas)": ["Retencions de no residents (lloguer, professionals i altres rendes)", "Non-resident withholdings (rent, professionals and other income)"],
  "Resumen anual de las retenciones de no residentes": ["Resum anual de les retencions de no residents", "Annual summary of non-resident withholdings"],
  "Operaciones de más de 3.005,06 € con un mismo cliente o proveedor": ["Operacions de més de 3.005,06 € amb un mateix client o proveïdor", "Transactions over €3,005.06 with the same client or supplier"],
  "Operaciones de más de 3.005,06 € (Agencia Tributaria Canaria)": ["Operacions de més de 3.005,06 € (Agència Tributària Canària)", "Transactions over €3,005.06 (Canary Islands Tax Agency)"],
  "Declaración de la renta": ["Declaració de la renda", "Income tax return"],
  "Impuesto sobre Sociedades": ["Impost sobre Societats", "Corporation tax"],
  "Operaciones vinculadas (solo si con un socio, administrador o sociedad del grupo pasas de 250.000 € en el año)": ["Operacions vinculades (només si amb un soci, administrador o societat del grup passes de 250.000 € a l'any)", "Related-party transactions (only if you exceed €250,000 a year with a shareholder, director or group company)"],
  "Impuesto sobre Actividades Económicas (solo con una cifra de negocios de 1 millón o más)": ["Impost sobre Activitats Econòmiques (només amb una xifra de negocis d'1 milió o més)", "Business activities tax, IAE (only with turnover of €1 million or more)"],
  "Legalizar los libros (diario, inventarios y cuentas anuales, y actas)": ["Legalitzar els llibres (diari, inventaris i comptes anuals, i actes)", "Legalise the books (journal, inventories and annual accounts, and minutes)"],
  "Depositar las cuentas anuales": ["Dipositar els comptes anuals", "File the annual accounts"],
  "Declaración censal (036/037): cuando cambia algo de tu actividad, domicilio o régimen": ["Declaració censal (036/037): quan canvia alguna cosa de la teva activitat, domicili o règim", "Census declaration (036/037): when something changes in your business, address or tax scheme"],
  "1 al 20 de abril, julio y octubre, y 1 al 30 de enero": ["De l'1 al 20 d'abril, juliol i octubre, i de l'1 al 30 de gener", "1–20 April, July and October, and 1–30 January"],
  "1 al 20 de abril, julio, octubre y enero": ["De l'1 al 20 d'abril, juliol, octubre i gener", "1–20 April, July, October and January"],
  "1 al 20 de abril, julio y octubre, y 1 al 31 de enero": ["De l'1 al 20 d'abril, juliol i octubre, i de l'1 al 31 de gener", "1–20 April, July and October, and 1–31 January"],
  "1 al 31 de enero": ["De l'1 al 31 de gener", "1–31 January"],
  "1 al 30 de enero": ["De l'1 al 30 de gener", "1–30 January"],
  "hasta el último día de abril, julio, octubre y enero": ["fins a l'últim dia d'abril, juliol, octubre i gener", "by the last day of April, July, October and January"],
  "febrero (solo si las hay)": ["febrer (només si n'hi ha)", "February (only if there are any)"],
  "abril a junio": ["d'abril a juny", "April to June"],
  "1 al 25 de julio": ["De l'1 al 25 de juliol", "1–25 July"],
  "1 al 20 de abril, octubre y diciembre (desde el segundo año, si el anterior salió a pagar)": ["De l'1 al 20 d'abril, octubre i desembre (a partir del segon any, si l'anterior va sortir a pagar)", "1–20 April, October and December (from the second year, if the previous one was payable)"],
  "1 al 30 de noviembre del año siguiente": ["De l'1 al 30 de novembre de l'any següent", "1–30 November of the following year"],
  "en diciembre, el año antes del primero en que toca pagarlo": ["al desembre, l'any abans del primer en què toca pagar-lo", "in December, the year before the first year it's due"],
  "hasta el 30 de abril": ["fins al 30 d'abril", "by 30 April"],
  "hasta el 30 de julio (un mes después de aprobarlas en junta, como tarde el 30 de junio)": ["fins al 30 de juliol (un mes després d'aprovar-los en junta, com a molt tard el 30 de juny)", "by 30 July (one month after they're approved at the general meeting, by 30 June at the latest)"],
  "en el mes siguiente al cambio": ["el mes següent al canvi", "in the month after the change"],
